const k3okw=(w,s)=>s.length<=3?(w===s||(w.startsWith(s)&&w.length<=s.length+2)):w.startsWith(s);
const K3SYN=[['картошк','Картофель'],['томат','Помидоры'],['огурец','Огурцы'],['кура','Курица'],['курочк','Курица'],['батон','Хлеб'],['хлебушек','Хлеб'],['булк','Булочки'],['сосиск','Колбаса'],['минералк','Вода'],['водичк','Вода'],['яйцо','Яйца'],['макарошк','Макароны'],['спагетти','Макароны'],['туалетн','Туалетная бумага'],['бананчик','Бананы'],['яблок','Яблоки'],['kartoffel','Картофель'],['tomate','Помидоры'],['ei','Яйца'],['brötchen','Булочки'],['semmel','Булочки'],['spaghetti','Макароны']];
function k3match(text){const w=k3low(text).split(/[^\p{L}]+/u).filter(Boolean);if(!w.length)return null;let best=null;for(const [sy,ru] of K3SYN){if(w.some(x=>sy.length<=3?x===sy:x.startsWith(sy))){const p=K3P.find(q=>q.n[0]===ru);if(p)best={p,sc:sy.length,len:1}}}
  K3ST.forEach(o=>o.stems.forEach(st=>{if(st.length>w.length)return;for(let a=0;a+st.length<=w.length;a++){if(st.every((s,k)=>k3okw(w[a+k],s))){const sc=st.join('').length;if(!best||sc>best.sc)best={p:o.p,sc,len:st.length}}}}));return best}
const k3name=p=>p.n[k3l()]||p.n[2];
const K3NUM={'один':1,'одну':1,'одна':1,'два':2,'две':2,'три':3,'четыре':4,'пять':5,'шесть':6,'десять':10,'ein':1,'eine':1,'einen':1,'zwei':2,'drei':3,'vier':4,'fünf':5,'sechs':6,'zehn':10,'one':1,'two':2,'three':3,'four':4,'five':5,'six':6,'ten':10,'jeden':1,'jedna':1,'dwa':2,'dwie':2,'trzy':3,'cztery':4,'pięć':5,'bir':1,'iki':2,'üç':3,'dört':4,'beş':5,'un':1,'une':1,'deux':2,'trois':3,'quatre':4,'cinq':5,'uno':1,'una':1,'dos':2,'tres':3,'cuatro':4,'cinco':5};
