   if(words.length>1){const each=words.map(w=>({w,m:k3match(w),n:K3NUM[k3low(w)]||(/^\d+$/.test(w)?+w:0)}));const known=each.filter(x=>x.m).length;if(known>=2&&each.every(x=>x.m||x.n||/^(кг|kg|г|g|л|l|шт|st)$/i.test(x.w))){let q='';each.forEach(x=>{if(x.n){q='×'+x.n;return}if(x.m){out.push(k3item(x.m.p,x.w,q));q=''}});return}}
   let q='',rest=ch;const mq=rest.match(/^(\d+(?:[.,]\d+)?)\s*(кг|kg|г|g|л|l|шт\.?|st\.?|stück)?\s+(.+)$/i);
   if(mq){q=mq[2]?mq[1]+' '+mq[2].replace(/\.$/,''):'×'+mq[1];rest=mq[3]}else{const w0=k3low(rest.split(/\s+/)[0]);if(K3NUM[w0]&&rest.split(/\s+/).length>1){q='×'+K3NUM[w0];rest=rest.split(/\s+/).slice(1).join(' ')}}
