function k3hist(t){const K=k3K(),k=k3low(t),h=K.hist[k]=K.hist[k]||{t,n:0,ds:[]};h.n++;h.t=t;h.ds=(h.ds||[]).concat(Date.now()).slice(-6)}
function k3freq(){const K=k3K(),fr={};Object.values(K.hist).forEach(h=>fr[h.t]=(fr[h.t]||0)+h.n);try{hy().forEach(p=>{const n=(p.buys||[]).length;if(n>=2)fr[k3cap(p.name)]=(fr[k3cap(p.name)]||0)+n})}catch(e){}
  let L=Object.entries(fr).sort((a,b)=>b[1]-a[1]).map(x=>x[0]);if(L.length<6){const pop=K3POP.map(t=>{const m3=k3match(t);return m3?k3name(m3.p):t});pop.forEach(t=>{if(!L.includes(t))L.push(t)})}return L.slice(0,10)}
/* what is probably running out: bought regularly and the usual gap has passed */
function k3due(){const now=Date.now(),day=864e5,out=[];const chk=(t,ds)=>{ds=(ds||[]).slice().sort((a,b)=>a-b);if(ds.length<2)return;const gap=(ds[ds.length-1]-ds[0])/(ds.length-1);if(gap<day)return;if(now-ds[ds.length-1]>=gap*.85)out.push(t)};
  Object.values(k3K().hist).forEach(h=>chk(h.t,h.ds));try{hy().forEach(p=>chk(k3cap(p.name),(p.buys||[]).map(b=>new Date(b.d).getTime()).filter(Boolean)))}catch(e){}return [...new Set(out)].slice(0,14)}
